import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)
    if not isinstance(url, str) or not url.strip():
        return ("Error: Invalid URL provided.", [])
    if not isinstance(filename, str) or not filename.strip():
        return ("Error: Invalid filename provided.", [])
    zip_path = DOWNLOAD_DIR / filename
    try:
        verify_cert = not ("localhost" in url or "127.0.0.1" in url)
        with requests.get(url, stream=True, timeout=30, verify=verify_cert) as r:
            r.raise_for_status()
            with open(zip_path, "wb") as f:
                for chunk in r.iter_content(chunk_size=8192):
                    if chunk:
                        f.write(chunk)
    except requests.RequestException as e:
        return (f"Error: Failed to download file from {url}: {e}", [])
    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            zf.extractall(ZIP_DIR)
    except (FileNotFoundError, zipfile.BadZipFile, OSError) as e:
        return (f"Error: Failed to extract zip file {zip_path}: {e}", [])
    extracted_files = []
    for p in ZIP_DIR.rglob("*"):
        if p.is_file():
            extracted_files.append(str(p.relative_to(ZIP_DIR)))
    return ("Download and extraction completed successfully.", extracted_files)
