import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    pattern = re.compile(r'https?://[^\s\'"<>]+')
    urls = pattern.findall(myString if isinstance(myString, str) else "")
    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        netloc = parsed.netloc
        if not netloc:
            continue
        if '@' in netloc:
            netloc = netloc.split('@', 1)[1]
        if ':' in netloc:
            netloc = netloc.split(':', 1)[0]
        netloc = netloc.strip().lower()
        if netloc:
            domains.add(netloc)
    result = {}
    base_endpoint = "http://ip-api.com/json/"
    for domain in domains:
        try:
            params = {}
            if API_KEY:
                params["key"] = API_KEY
            response = requests.get(base_endpoint + domain, params=params, timeout=10)
            response.raise_for_status()
            try:
                data = response.json()
            except json.JSONDecodeError:
                data = None
            result[domain] = data
        except requests.RequestException:
            result[domain] = None
    return result
