            except Exception as e:
                raise Exception(f"Invalid data format: {e}")
        if not data:
            raise Exception("Empty data received from API")
        if isinstance(data, dict):
            if "data" in data and isinstance(data["data"], list):
                data = data["data"]
            else:
                data = [data]
        df = pd.DataFrame(data)
        if df.empty:
            raise Exception("DataFrame is empty")
        numeric_df = df.select_dtypes(include="number")
        if numeric_df.empty:
            raise Exception("No numeric data available for correlation")
        corr = numeric_df.corr()
        ax = sns.heatmap(corr, annot=False)
        return df, ax
    except Exception as e:
        raise Exception(f"Failed to retrieve or process data: {e}")
